SELECT city, CASE WHEN rating >= 3.8 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, AVG(rating) FILTER (WHERE country = 'DE') AS de_avg_rating, COUNT_IF(country = 'US') AS us_events, MAX(rating) FILTER (WHERE city = 'Singapore') AS singapore_max_rating, COUNT(DISTINCT city) AS distinct_cities, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS rating_per_singapore FROM suppliers GROUP BY CUBE (city, CASE WHEN rating >= 3.8 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY rating_per_singapore DESC NULLS LAST
